CREATE FUNCTION public.capture_portfolio_item_snapshot(
 p_portfolio_id uuid, p_section text, p_item_id uuid,
 p_refresh boolean DEFAULT false, p_expected_revision text DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
 uid uuid := auth.uid(); lib text; rel text; col text; imgs text;
 payload jsonb; rev text; old_data jsonb; old_rev text; version bigint;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.portfolios WHERE id=p_portfolio_id AND user_id=uid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Portfolio access denied' USING ERRCODE='42501'; END IF;
 CASE p_section
 WHEN 'education' THEN lib:='user_library_educations'; rel:='portfolio_educations'; col:='education_id'; imgs:=NULL;
 WHEN 'activity' THEN lib:='user_library_activities'; rel:='portfolio_activities'; col:='activity_id'; imgs:='user_library_activity_images';
 WHEN 'certificate' THEN lib:='user_library_certificates'; rel:='portfolio_certificates'; col:='certificate_id'; imgs:='user_library_certificate_images';
 ELSE RAISE EXCEPTION 'Invalid section' USING ERRCODE='22023'; END CASE;
 IF p_refresh IS NULL THEN RAISE EXCEPTION 'Invalid refresh mode' USING ERRCODE='22023'; END IF;
 EXECUTE format('SELECT snapshot_data,snapshot_revision,snapshot_version FROM public.%I WHERE portfolio_id=$1 AND %I=$2 FOR UPDATE',rel,col)
 INTO old_data,old_rev,version USING p_portfolio_id,p_item_id;
 IF version IS NULL THEN RAISE EXCEPTION 'Item is not selected' USING ERRCODE='22023'; END IF;
 -- Parent lock serializes capture against source deletion. Data and image rows are
 -- read in one statement, so a capture never combines two SQL statement snapshots.
 EXECUTE format('SELECT 1 FROM public.%I WHERE id=$1 AND user_id=$2 FOR SHARE',lib) USING p_item_id,uid;
 IF imgs IS NULL THEN
  EXECUTE format('SELECT jsonb_build_object(''item'',to_jsonb(l)-''updated_at'',''images'',''[]''::jsonb) FROM public.%I l WHERE id=$1 AND user_id=$2',lib) INTO payload USING p_item_id,uid;
 ELSE
  EXECUTE format('SELECT jsonb_build_object(''item'',to_jsonb(l)-''updated_at'',''images'',coalesce((SELECT jsonb_agg(to_jsonb(i) ORDER BY i.sort_order,i.id) FROM public.%I i WHERE i.%I=l.id),''[]''::jsonb)) FROM public.%I l WHERE l.id=$1 AND l.user_id=$2',imgs,col,lib) INTO payload USING p_item_id,uid;
 END IF;
 IF payload IS NULL THEN RAISE EXCEPTION 'Library access denied' USING ERRCODE='42501'; END IF;
 rev:=pg_catalog.md5(payload::text);
 IF old_data IS NOT NULL AND NOT p_refresh THEN
  RETURN jsonb_build_object('data',old_data,'revision',old_rev,'version',version,'latest_revision',rev);
 END IF;
 IF p_refresh AND (p_expected_revision IS NULL OR p_expected_revision IS DISTINCT FROM rev) THEN
  -- A stale reviewed revision is a permanent conflict for this request, not a
  -- serialization failure. PostgREST 14 can endlessly retry custom 40001 errors.
  RAISE EXCEPTION 'Source changed; inspect again' USING ERRCODE='PT409';
 END IF;
 IF old_data IS NULL OR old_data IS DISTINCT FROM payload THEN
  version:=version+1;
  EXECUTE format('UPDATE public.%I SET snapshot_data=$3,snapshot_revision=$4,snapshot_version=$5 WHERE portfolio_id=$1 AND %I=$2',rel,col)
   USING p_portfolio_id,p_item_id,payload,rev,version;
 END IF;
 RETURN jsonb_build_object('data',payload,'revision',rev,'version',version,'latest_revision',rev);
END $$;
REVOKE ALL ON FUNCTION public.capture_portfolio_item_snapshot(uuid,text,uuid,boolean,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.capture_portfolio_item_snapshot(uuid,text,uuid,boolean,text) TO authenticated;
create or replace function public.replace_portfolio_selection(
  p_portfolio_id uuid,
  p_section text,
  p_item_ids uuid[]
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_library text;
  v_relation text;
  v_column text;
  v_count integer;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  -- Serialize edits to the same portfolio and verify ownership before writing.
  perform 1 from public.portfolios
    where id = p_portfolio_id and user_id = v_user_id for update;
  if not found then
    raise exception 'Portfolio not found or access denied' using errcode = '42501';
  end if;

  case p_section
    when 'education' then
      v_library := 'user_library_educations';
      v_relation := 'portfolio_educations';
      v_column := 'education_id';
    when 'activity' then
      v_library := 'user_library_activities';
      v_relation := 'portfolio_activities';
      v_column := 'activity_id';
    when 'certificate' then
      v_library := 'user_library_certificates';
      v_relation := 'portfolio_certificates';
      v_column := 'certificate_id';
    else raise exception 'Invalid section' using errcode = '22023';
  end case;

  if p_item_ids is null or array_position(p_item_ids, null) is not null then
    raise exception 'Item IDs must be a non-null array' using errcode = '22023';
  end if;
  if cardinality(p_item_ids) <> (select count(distinct item) from unnest(p_item_ids) item) then
    raise exception 'Duplicate item IDs' using errcode = '22023';
  end if;

  execute format('select count(*) from public.%I where user_id = $1 and id = any($2)', v_library)
    into v_count using v_user_id, p_item_ids;
  if v_count <> cardinality(p_item_ids) then
    raise exception 'Library item not found or access denied' using errcode = '42501';
  end if;

  execute format('delete from public.%I where portfolio_id = $1 and not (%I = any($2))', v_relation, v_column)
    using p_portfolio_id, p_item_ids;
  execute format(
    'insert into public.%I (portfolio_id, %I, sort_order) select $1, item, (position - 1)::integer from unnest($2::uuid[]) with ordinality as selection(item, position) on conflict (portfolio_id, %I) do update set sort_order=excluded.sort_order',
    v_relation, v_column, v_column
  ) using p_portfolio_id, p_item_ids;
  perform public.capture_portfolio_item_snapshot(p_portfolio_id,p_section,item) from unnest(p_item_ids) item;
end;
$$;
revoke all on function public.replace_portfolio_selection(uuid, text, uuid[]) from public;
revoke all on function public.replace_portfolio_selection(uuid, text, uuid[]) from anon;
grant execute on function public.replace_portfolio_selection(uuid, text, uuid[]) to authenticated;

-- Source: atomic-library-update.sql SHA256 7118bc2a757df371bea91139d88c6184831b0a98e1a4bd894260e1a816354617

CREATE FUNCTION public.update_library_item_atomic(
  p_section text, p_item_id uuid, p_fields jsonb, p_images jsonb, p_tag_ids uuid[]
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  uid uuid := auth.uid();
  source_table text; image_table text; tag_table text; parent_column text;
  allowed_fields text[]; field_name text; assignments text;
  original jsonb; updated jsonb; image jsonb; image_id uuid; stored_url text;
  retained_ids uuid[] := '{}'; image_limit integer; new_count integer := 0;
  position integer := 0;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  CASE p_section
    WHEN 'education' THEN
      source_table := 'user_library_educations'; parent_column := 'education_id';
      allowed_fields := ARRAY['level','school_name','study_plan','gpa','start_year','end_year','logo_url'];
    WHEN 'activity' THEN
      source_table := 'user_library_activities'; parent_column := 'activity_id';
      image_table := 'user_library_activity_images'; image_limit := 4;
      allowed_fields := ARRAY['title','description','activity_date','organization'];
    WHEN 'certificate' THEN
      source_table := 'user_library_certificates'; parent_column := 'certificate_id';
      image_table := 'user_library_certificate_images'; image_limit := 2;
      allowed_fields := ARRAY['title','description','issued_by','issued_date'];
    ELSE RAISE EXCEPTION 'Invalid section' USING ERRCODE = '22023';
  END CASE;
  tag_table := 'user_library_' || p_section || '_tags';
  IF jsonb_typeof(p_fields) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_images) IS DISTINCT FROM 'array'
    OR p_tag_ids IS NULL OR array_position(p_tag_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid save payload' USING ERRCODE = '22023';
  END IF;
  IF cardinality(p_tag_ids) <> (SELECT count(DISTINCT id) FROM unnest(p_tag_ids) id) THEN
    RAISE EXCEPTION 'Duplicate tags' USING ERRCODE = '22023';
  END IF;
  FOR field_name IN SELECT jsonb_object_keys(p_fields) LOOP
    IF NOT field_name = ANY(allowed_fields) THEN
      RAISE EXCEPTION 'Unsupported field' USING ERRCODE = '22023';
    END IF;
    IF jsonb_typeof(p_fields->field_name) NOT IN ('string','null')
      AND NOT (field_name = 'gpa' AND jsonb_typeof(p_fields->field_name) = 'number') THEN
      RAISE EXCEPTION 'Invalid field type' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  -- All content writers must take this parent lock before mutating image rows.
  -- Snapshot capture takes FOR SHARE on the same row.
  EXECUTE format('SELECT to_jsonb(l) FROM public.%I l WHERE id=$1 AND user_id=$2 FOR UPDATE', source_table)
    INTO original USING p_item_id, uid;
  IF original IS NULL THEN
    RAISE EXCEPTION 'Source unavailable' USING ERRCODE = '42501';
  END IF;
  updated := original || p_fields;
  IF p_section = 'education' THEN
    IF coalesce(btrim(updated->>'school_name'),'') = '' OR coalesce(btrim(updated->>'level'),'') = '' THEN
      RAISE EXCEPTION 'Required education fields missing' USING ERRCODE = '22023';
    END IF;
    IF updated->>'gpa' IS NOT NULL AND ((updated->>'gpa')::numeric NOT BETWEEN 0 AND 4) THEN
      RAISE EXCEPTION 'Invalid GPA' USING ERRCODE = '22023';
    END IF;
    IF jsonb_array_length(p_images) <> 0 THEN
      RAISE EXCEPTION 'Education uses a logo field' USING ERRCODE = '22023';
    END IF;
  ELSIF coalesce(btrim(updated->>'title'),'') = '' THEN
    RAISE EXCEPTION 'Title required' USING ERRCODE = '22023';
  END IF;
  IF (SELECT count(*) FROM public.user_tags WHERE user_id=uid AND id=ANY(p_tag_ids)) <> cardinality(p_tag_ids) THEN
    RAISE EXCEPTION 'Tag access denied' USING ERRCODE = '42501';
  END IF;

  IF image_table IS NOT NULL THEN
    FOR image IN SELECT value FROM jsonb_array_elements(p_images) LOOP
      IF jsonb_typeof(image) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'Invalid image' USING ERRCODE = '22023';
      END IF;
      IF EXISTS (SELECT 1 FROM jsonb_object_keys(image) key WHERE key NOT IN ('id','image_url'))
        OR jsonb_typeof(image->'image_url') IS DISTINCT FROM 'string'
        OR btrim(image->>'image_url') = '' THEN
        RAISE EXCEPTION 'Invalid image fields' USING ERRCODE = '22023';
      END IF;
      image_id := (image->>'id')::uuid;
      IF image_id IS NULL THEN
        new_count := new_count + 1;
      ELSE
        IF image_id=ANY(retained_ids) THEN
          RAISE EXCEPTION 'Duplicate image' USING ERRCODE = '22023';
        END IF;
        EXECUTE format('SELECT image_url FROM public.%I WHERE id=$1 AND %I=$2',image_table,parent_column)
          INTO stored_url USING image_id,p_item_id;
        IF stored_url IS NULL OR stored_url IS DISTINCT FROM image->>'image_url' THEN
          RAISE EXCEPTION 'Image access denied or changed' USING ERRCODE = '42501';
        END IF;
        retained_ids := array_append(retained_ids,image_id);
      END IF;
    END LOOP;
    -- Preserve legacy over-limit rows; only additions must fit the current ceiling.
    IF new_count > 0 AND jsonb_array_length(p_images) > image_limit THEN
      RAISE EXCEPTION 'Image limit exceeded' USING ERRCODE = '23514';
    END IF;
  END IF;

  SELECT string_agg(format('%I=r.%I', key, key), ', ' ORDER BY key)
    INTO assignments FROM jsonb_object_keys(p_fields) key;
  IF assignments IS NOT NULL THEN
    EXECUTE format('UPDATE public.%I l SET %s FROM jsonb_populate_record(NULL::public.%I,$3) r WHERE l.id=$1 AND l.user_id=$2 RETURNING to_jsonb(l)',source_table,assignments,source_table)
      INTO updated USING p_item_id,uid,updated;
  END IF;
  IF image_table IS NOT NULL THEN
    EXECUTE format('DELETE FROM public.%I WHERE %I=$1 AND NOT (id=ANY($2))',image_table,parent_column)
      USING p_item_id,retained_ids;
    FOR image IN SELECT value FROM jsonb_array_elements(p_images) LOOP
      image_id := (image->>'id')::uuid;
      IF image_id IS NULL THEN
        EXECUTE format('INSERT INTO public.%I (%I,image_url,sort_order) VALUES($1,$2,$3)',image_table,parent_column)
          USING p_item_id,image->>'image_url',position;
      ELSE
        EXECUTE format('UPDATE public.%I SET sort_order=$3 WHERE id=$1 AND %I=$2',image_table,parent_column)
          USING image_id,p_item_id,position;
      END IF;
      position := position + 1;
    END LOOP;
  END IF;
  EXECUTE format('DELETE FROM public.%I WHERE %I=$1',tag_table,parent_column) USING p_item_id;
  EXECUTE format('INSERT INTO public.%I (%I,tag_id) SELECT $1,id FROM unnest($2::uuid[]) id',tag_table,parent_column)
    USING p_item_id,p_tag_ids;
  -- A single statement/RPC transaction commits text, logo, image rows and tag links together.
  -- It does NOT make Storage upload or network acknowledgement transactional.
  RETURN jsonb_build_object('id',p_item_id,'item',updated);
END $$;
REVOKE ALL ON FUNCTION public.update_library_item_atomic(text,uuid,jsonb,jsonb,uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_library_item_atomic(text,uuid,jsonb,jsonb,uuid[]) TO authenticated;

-- Prototype enforcement: old multi-request content/image writers must fail, not bypass the lock.
REVOKE INSERT, UPDATE ON public.user_library_educations,public.user_library_activities,public.user_library_certificates FROM PUBLIC,anon,authenticated;
REVOKE INSERT, UPDATE, DELETE ON public.user_library_activity_images,public.user_library_certificate_images FROM PUBLIC,anon,authenticated;

-- Source: atomic-library-create.sql SHA256 1ff740b5fbd35d8a8c045ddbd8c17792d4c521d13b42397de1110df9335a74a0
CREATE TABLE public.library_create_receipts (
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  item_id uuid NOT NULL,
  section text NOT NULL CHECK (section IN ('education','activity','certificate')),
  request_fingerprint text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id,item_id)
);
-- No source FK: deleting a source must not make replay recreate it.
ALTER TABLE public.library_create_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.library_create_receipts FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.library_create_receipts TO authenticated;
CREATE POLICY own_library_create_receipts ON public.library_create_receipts
  FOR SELECT TO authenticated USING (user_id=(SELECT auth.uid()));

CREATE FUNCTION public.create_library_item_atomic(
  p_section text, p_item_id uuid, p_fields jsonb, p_images jsonb, p_tag_ids uuid[]
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  uid uuid := auth.uid(); source_table text; allowed_fields text[];
  receipt public.library_create_receipts%ROWTYPE;
  fingerprint text; columns_sql text; values_sql text;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  IF p_item_id IS NULL OR jsonb_typeof(p_fields) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_images) IS DISTINCT FROM 'array' OR p_tag_ids IS NULL THEN
    RAISE EXCEPTION 'Invalid create payload' USING ERRCODE='22023';
  END IF;
  CASE p_section
    WHEN 'education' THEN
      source_table := 'user_library_educations';
      allowed_fields := ARRAY['level','school_name','study_plan','gpa','start_year','end_year','logo_url'];
      IF coalesce(btrim(p_fields->>'level'),'')='' OR coalesce(btrim(p_fields->>'school_name'),'')='' THEN
        RAISE EXCEPTION 'Required education fields missing' USING ERRCODE='22023';
      END IF;
    WHEN 'activity' THEN
      source_table := 'user_library_activities';
      allowed_fields := ARRAY['title','description','activity_date','organization'];
    WHEN 'certificate' THEN
      source_table := 'user_library_certificates';
      allowed_fields := ARRAY['title','description','issued_by','issued_date'];
    ELSE RAISE EXCEPTION 'Invalid section' USING ERRCODE='22023';
  END CASE;
  IF p_section<>'education' AND coalesce(btrim(p_fields->>'title'),'')='' THEN
    RAISE EXCEPTION 'Title required' USING ERRCODE='22023';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_fields) key WHERE NOT key=ANY(allowed_fields)) THEN
    RAISE EXCEPTION 'Unsupported field' USING ERRCODE='22023';
  END IF;
  fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'section',p_section,'fields',p_fields,'images',p_images,'tags',p_tag_ids
  )::text,'UTF8')),'hex');
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('library-create:'||uid::text||':'||p_item_id::text,0));
  SELECT * INTO receipt FROM public.library_create_receipts WHERE user_id=uid AND item_id=p_item_id;
  IF FOUND THEN
    IF receipt.section<>p_section OR receipt.request_fingerprint<>fingerprint THEN
      RAISE EXCEPTION 'Create key reused with different arguments' USING ERRCODE='22023';
    END IF;
    RETURN jsonb_build_object('id',p_item_id,'status','confirmed');
  END IF;
  -- A preexisting source without this receipt is never treated as a successful create.
  -- Plain INSERT, not upsert: stale creates cannot overwrite an existing item.
  SELECT string_agg(format('%I',key),',' ORDER BY key), string_agg(format('r.%I',key),',' ORDER BY key)
    INTO columns_sql,values_sql FROM jsonb_object_keys(p_fields) key;
  EXECUTE format('INSERT INTO public.%I (id,user_id,%s) SELECT $1,$2,%s FROM jsonb_populate_record(NULL::public.%I,$3) r',source_table,columns_sql,values_sql,source_table)
    USING p_item_id,uid,p_fields;
  -- Reuse update validation, image limits, image ownership, tag ownership and write ordering.
  -- A failure here rolls back the source INSERT and leaves no receipt.
  PERFORM public.update_library_item_atomic(p_section,p_item_id,p_fields,p_images,p_tag_ids);
  INSERT INTO public.library_create_receipts(user_id,item_id,section,request_fingerprint)
    VALUES(uid,p_item_id,p_section,fingerprint);
  RETURN jsonb_build_object('id',p_item_id,'status','confirmed');
END $$;
REVOKE ALL ON FUNCTION public.create_library_item_atomic(text,uuid,jsonb,jsonb,uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_library_item_atomic(text,uuid,jsonb,jsonb,uuid[]) TO authenticated;

-- Source: snapshot-upload-validation.sql SHA256 5a3756b2ec0c1fc0b841e57556403d9687097eb43cc2efc2e234b1dbcefc825b
CREATE SCHEMA IF NOT EXISTS portfolio_private;
REVOKE ALL ON SCHEMA portfolio_private FROM PUBLIC,anon,authenticated;
CREATE TABLE portfolio_private.asset_config (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 public_base_url text NOT NULL CHECK(public_base_url ~ '^https://[^/?#]+/storage/v1/object/public/portfolio-images/$')
);
REVOKE ALL ON portfolio_private.asset_config FROM PUBLIC,anon,authenticated;
CREATE FUNCTION portfolio_private.validate_library_upload() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); owner_id uuid; item_id uuid; section_path text;
 asset_url text; base_url text; object_path text; prefix text; found_object uuid;
BEGIN
 CASE TG_TABLE_NAME
 WHEN 'user_library_educations' THEN
  owner_id:=NEW.user_id; item_id:=NEW.id; section_path:='education'; asset_url:=NEW.logo_url;
  IF TG_OP='UPDATE' AND NEW.logo_url IS NOT DISTINCT FROM OLD.logo_url THEN RETURN NEW; END IF;
 WHEN 'user_library_activity_images' THEN
  item_id:=NEW.activity_id; section_path:='activities'; asset_url:=NEW.image_url;
  SELECT user_id INTO owner_id FROM public.user_library_activities WHERE id=item_id;
  IF TG_OP='UPDATE' AND NEW.image_url IS NOT DISTINCT FROM OLD.image_url AND NEW.activity_id=OLD.activity_id THEN RETURN NEW; END IF;
 WHEN 'user_library_certificate_images' THEN
  item_id:=NEW.certificate_id; section_path:='certificates'; asset_url:=NEW.image_url;
  SELECT user_id INTO owner_id FROM public.user_library_certificates WHERE id=item_id;
  IF TG_OP='UPDATE' AND NEW.image_url IS NOT DISTINCT FROM OLD.image_url AND NEW.certificate_id=OLD.certificate_id THEN RETURN NEW; END IF;
 ELSE RAISE EXCEPTION 'Unsupported asset writer' USING ERRCODE='22023';
 END CASE;
 IF asset_url IS NULL AND section_path='education' THEN RETURN NEW; END IF;
 IF actor IS NULL OR owner_id IS DISTINCT FROM actor THEN
  RAISE EXCEPTION 'Asset owner mismatch' USING ERRCODE='42501';
 END IF;
 SELECT public_base_url INTO base_url FROM portfolio_private.asset_config WHERE singleton;
 IF base_url IS NULL THEN RAISE EXCEPTION 'Asset origin not configured' USING ERRCODE='55000'; END IF;
 prefix:=base_url||'users/'||actor::text||'/'||section_path||'/'||item_id::text||'/';
 IF asset_url IS NULL OR left(asset_url,length(prefix))<>prefix
 OR substring(asset_url FROM length(prefix)+1) !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|jpeg|png|webp)$' THEN
  RAISE EXCEPTION 'Invalid upload reference' USING ERRCODE='22023';
 END IF;
 object_path:=substring(asset_url FROM length(base_url)+1);
 SELECT id INTO found_object FROM storage.objects
  WHERE bucket_id='portfolio-images' AND name=object_path AND storage.objects.owner_id=actor::text
  FOR SHARE;
 IF found_object IS NULL THEN RAISE EXCEPTION 'Owned upload not found' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION portfolio_private.validate_library_upload() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_education_upload BEFORE INSERT OR UPDATE OF logo_url ON public.user_library_educations FOR EACH ROW EXECUTE FUNCTION portfolio_private.validate_library_upload();
CREATE TRIGGER validate_activity_upload BEFORE INSERT OR UPDATE OF image_url,activity_id ON public.user_library_activity_images FOR EACH ROW EXECUTE FUNCTION portfolio_private.validate_library_upload();
CREATE TRIGGER validate_certificate_upload BEFORE INSERT OR UPDATE OF image_url,certificate_id ON public.user_library_certificate_images FOR EACH ROW EXECUTE FUNCTION portfolio_private.validate_library_upload();

-- Source: snapshot-transition-read.sql SHA256 0b4236898062b15c43a4540bb110cc4ecefd5fb60a632cfcfc282bb6cd8f39a2

-- Explicit, replay-safe preparation. Captures today's content, never invented history.
-- All three sections transition in one transaction; existing editions are left intact.
CREATE FUNCTION public.prepare_portfolio_item_snapshots(p_portfolio_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  uid uuid := auth.uid(); section_name text; relation_name text; item_column text;
  selected record; prepared integer := 0;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.portfolios WHERE id=p_portfolio_id AND user_id=uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Portfolio access denied' USING ERRCODE='42501'; END IF;

  FOREACH section_name IN ARRAY ARRAY['education','activity','certificate'] LOOP
    relation_name := CASE section_name WHEN 'education' THEN 'portfolio_educations'
      WHEN 'activity' THEN 'portfolio_activities' ELSE 'portfolio_certificates' END;
    item_column := section_name || '_id';
    FOR selected IN EXECUTE format(
      'SELECT %I AS item_id,snapshot_data,snapshot_revision,snapshot_version
       FROM public.%I WHERE portfolio_id=$1 ORDER BY sort_order,%I FOR UPDATE',
      item_column,relation_name,item_column) USING p_portfolio_id
    LOOP
      IF selected.snapshot_data IS NULL AND selected.snapshot_revision IS NULL
         AND selected.snapshot_version=0 THEN
        PERFORM public.capture_portfolio_item_snapshot(p_portfolio_id,section_name,selected.item_id);
        prepared := prepared+1;
      ELSIF selected.snapshot_data IS NULL
         OR jsonb_typeof(selected.snapshot_data->'item') IS DISTINCT FROM 'object'
         OR jsonb_typeof(selected.snapshot_data->'images') IS DISTINCT FROM 'array'
         OR selected.snapshot_data->'item'->>'id' IS DISTINCT FROM selected.item_id::text
         OR selected.snapshot_data->'item'->>'user_id' IS DISTINCT FROM uid::text
         OR selected.snapshot_version < 1
         OR selected.snapshot_revision IS DISTINCT FROM md5(selected.snapshot_data::text) THEN
        -- An incomplete/corrupt edition is not an old portfolio. Never silently recapture it.
        RAISE EXCEPTION 'Invalid stored snapshot' USING ERRCODE='22023';
      END IF;
    END LOOP;
  END LOOP;
  RETURN jsonb_build_object('portfolio_id',p_portfolio_id,'prepared_count',prepared);
END $$;
REVOKE ALL ON FUNCTION public.prepare_portfolio_item_snapshots(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.prepare_portfolio_item_snapshots(uuid) TO authenticated;

-- An ordinary read must never accept a newer edition or prepare an old portfolio.
-- Invoker security preserves table RLS; owner checks also reject foreign/missing portfolios.
CREATE FUNCTION public.read_portfolio_item_snapshots(p_portfolio_id uuid,p_section text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path = '' AS $$
DECLARE
  uid uuid := auth.uid(); library_name text; relation_name text; item_column text;
  image_table text; source_expression text; result jsonb; entry jsonb;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.portfolios WHERE id=p_portfolio_id AND user_id=uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'Portfolio access denied' USING ERRCODE='42501'; END IF;
  CASE p_section
    WHEN 'education' THEN library_name:='user_library_educations'; relation_name:='portfolio_educations';
    WHEN 'activity' THEN library_name:='user_library_activities'; relation_name:='portfolio_activities'; image_table:='user_library_activity_images';
    WHEN 'certificate' THEN library_name:='user_library_certificates'; relation_name:='portfolio_certificates'; image_table:='user_library_certificate_images';
    ELSE RAISE EXCEPTION 'Invalid section' USING ERRCODE='22023';
  END CASE;
  item_column := p_section || '_id';
  -- Same canonical content as capture: updated_at is excluded and image order is deterministic.
  source_expression := 'jsonb_build_object(''item'',to_jsonb(l)-''updated_at'',''images'',''[]''::jsonb)';
  IF image_table IS NOT NULL THEN
    source_expression := format('jsonb_build_object(''item'',to_jsonb(l)-''updated_at'',''images'',
      coalesce((SELECT jsonb_agg(to_jsonb(i) ORDER BY i.sort_order,i.id)
        FROM public.%I i WHERE i.%I=l.id),''[]''::jsonb))',image_table,item_column);
  END IF;
  EXECUTE format('SELECT coalesce(jsonb_agg(jsonb_build_object(
      ''item_id'',r.%I,''sort_order'',r.sort_order,''data'',r.snapshot_data,
      ''revision'',r.snapshot_revision,''version'',r.snapshot_version,
      ''latest_revision'',CASE WHEN l.id IS NOT NULL THEN md5((%s)::text) END
    ) ORDER BY r.sort_order,r.%I),''[]''::jsonb)
    FROM public.%I r LEFT JOIN public.%I l ON l.id=r.%I AND l.user_id=$2
    WHERE r.portfolio_id=$1',item_column,source_expression,item_column,relation_name,library_name,item_column)
    INTO result USING p_portfolio_id,uid;

  FOR entry IN SELECT value FROM jsonb_array_elements(result) LOOP
    IF entry->'data' = 'null'::jsonb AND entry->'revision' = 'null'::jsonb
       AND (entry->>'version')::bigint=0 THEN
      RAISE EXCEPTION 'Snapshot preparation required' USING ERRCODE='55000';
    END IF;
    IF jsonb_typeof(entry->'data'->'item') IS DISTINCT FROM 'object'
       OR jsonb_typeof(entry->'data'->'images') IS DISTINCT FROM 'array'
       OR entry->'data'->'item'->>'id' IS DISTINCT FROM entry->>'item_id'
       OR entry->'data'->'item'->>'user_id' IS DISTINCT FROM uid::text
       OR (entry->>'version')::bigint < 1
       OR entry->>'revision' IS DISTINCT FROM md5((entry->'data')::text)
       OR entry->>'latest_revision' IS NULL THEN
      RAISE EXCEPTION 'Invalid stored snapshot or inaccessible source' USING ERRCODE='22023';
    END IF;
  END LOOP;
  RETURN jsonb_build_object('format_version',1,'portfolio_id',p_portfolio_id,'section',p_section,'items',result);
END $$;
REVOKE ALL ON FUNCTION public.read_portfolio_item_snapshots(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.read_portfolio_item_snapshots(uuid,text) TO authenticated;

-- Source: snapshot-portfolio-copy.sql SHA256 7fd74666d743340d75a928deb965afb5b2ce448e4ac75db17bfa84fb74e9325e
CREATE OR REPLACE FUNCTION public.perform_portfolio_action(p_request_id uuid,p_action text,p_source_id uuid,p_title text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); receipt public.portfolio_action_receipts%ROWTYPE; new_id uuid; snapshot jsonb; outcome text:='rejected';
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR p_source_id IS NULL OR p_action IS NULL OR p_action NOT IN ('duplicate','delete') OR p_title IS NULL OR
 (p_action='duplicate' AND p_title !~ '[^[:space:]]') OR (p_action='delete' AND p_title<>'') THEN RAISE EXCEPTION 'Invalid request' USING ERRCODE='22023'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor::text||':'||p_request_id::text,0));
 SELECT * INTO receipt FROM public.portfolio_action_receipts WHERE user_id=actor AND request_id=p_request_id;
 IF FOUND THEN
  IF receipt.action<>p_action OR receipt.source_id<>p_source_id OR receipt.title<>p_title THEN RAISE EXCEPTION 'Request key reused with different arguments' USING ERRCODE='22023'; END IF;
  RETURN pg_catalog.to_jsonb(receipt)-'user_id'-'created_at';
 END IF;
 PERFORM 1 FROM public.portfolios WHERE id=p_source_id AND user_id=actor FOR UPDATE;
 IF FOUND THEN
  IF p_action='delete' THEN
   DELETE FROM public.portfolios WHERE id=p_source_id AND user_id=actor RETURNING id INTO new_id;
   IF new_id IS NULL THEN RAISE EXCEPTION 'Delete returned no row'; END IF;
  ELSE
   SELECT pg_catalog.jsonb_build_object('portfolio',pg_catalog.to_jsonb(p),
'covers',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(c)) FROM public.covers c WHERE c.portfolio_id=p.id),'[]'::jsonb),
'prefaces',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(c)) FROM public.prefaces c WHERE c.portfolio_id=p.id),'[]'::jsonb),
'profiles',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(c)) FROM public.profiles c WHERE c.portfolio_id=p.id),'[]'::jsonb),
'activities',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(c)) FROM public.activities c WHERE c.portfolio_id=p.id),'[]'::jsonb),
'certificates',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(c)) FROM public.certificates c WHERE c.portfolio_id=p.id),'[]'::jsonb),
'educations',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(c)) FROM public.educations c WHERE c.portfolio_id=p.id),'[]'::jsonb),
'portfolio_educations',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(c)) FROM public.portfolio_educations c WHERE c.portfolio_id=p.id),'[]'::jsonb),
'portfolio_activities',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(c)) FROM public.portfolio_activities c WHERE c.portfolio_id=p.id),'[]'::jsonb),
'portfolio_certificates',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(c)) FROM public.portfolio_certificates c WHERE c.portfolio_id=p.id),'[]'::jsonb),
'portfolio_section_visibility',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(c)) FROM public.portfolio_section_visibility c WHERE c.portfolio_id=p.id),'[]'::jsonb)) INTO snapshot FROM public.portfolios p WHERE p.id=p_source_id AND p.user_id=actor;
IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_populate_recordset(NULL::public.portfolio_activities,snapshot->'portfolio_activities') x LEFT JOIN public.user_library_activities l ON l.id=x.activity_id AND l.user_id=actor WHERE l.id IS NULL) THEN RAISE EXCEPTION 'Invalid library ownership' USING ERRCODE='42501'; END IF;
IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_populate_recordset(NULL::public.portfolio_certificates,snapshot->'portfolio_certificates') x LEFT JOIN public.user_library_certificates l ON l.id=x.certificate_id AND l.user_id=actor WHERE l.id IS NULL) THEN RAISE EXCEPTION 'Invalid library ownership' USING ERRCODE='42501'; END IF;
IF EXISTS(SELECT 1 FROM pg_catalog.jsonb_populate_recordset(NULL::public.portfolio_educations,snapshot->'portfolio_educations') x LEFT JOIN public.user_library_educations l ON l.id=x.education_id AND l.user_id=actor WHERE l.id IS NULL) THEN RAISE EXCEPTION 'Invalid library ownership' USING ERRCODE='42501'; END IF;
-- Copy only captured content. Missing snapshots require explicit transition first;
-- do not silently capture current library content during duplication.
IF EXISTS (
 SELECT 1 FROM pg_catalog.jsonb_populate_recordset(NULL::public.portfolio_educations,snapshot->'portfolio_educations') x WHERE x.snapshot_data IS NULL OR x.snapshot_revision IS NULL OR x.snapshot_version < 1
 UNION ALL
 SELECT 1 FROM pg_catalog.jsonb_populate_recordset(NULL::public.portfolio_activities,snapshot->'portfolio_activities') x WHERE x.snapshot_data IS NULL OR x.snapshot_revision IS NULL OR x.snapshot_version < 1
 UNION ALL
 SELECT 1 FROM pg_catalog.jsonb_populate_recordset(NULL::public.portfolio_certificates,snapshot->'portfolio_certificates') x WHERE x.snapshot_data IS NULL OR x.snapshot_revision IS NULL OR x.snapshot_version < 1
) THEN RAISE EXCEPTION 'Snapshot transition required before duplicate' USING ERRCODE='55000'; END IF;
INSERT INTO public.portfolios(user_id,title,template_key,theme_color) SELECT actor,p_title,p.template_key,p.theme_color FROM pg_catalog.jsonb_populate_record(NULL::public.portfolios,snapshot->'portfolio') p RETURNING id INTO new_id;
INSERT INTO public.covers(portfolio_id,cover_image_url,title,subtitle,school_name,first_name,last_name) SELECT new_id,cover_image_url,title,subtitle,school_name,first_name,last_name FROM pg_catalog.jsonb_populate_recordset(NULL::public.covers,snapshot->'covers');
INSERT INTO public.prefaces(portfolio_id,content,signature_name) SELECT new_id,content,signature_name FROM pg_catalog.jsonb_populate_recordset(NULL::public.prefaces,snapshot->'prefaces');
INSERT INTO public.profiles(portfolio_id,profile_image_url,first_name,last_name,nickname,date_of_birth,blood_group,address,phone,contact_email,social_links,talents,motto,nationality,ethnicity,religion,school,plan,gpax,custom_fields,age_mode,manual_age) SELECT new_id,profile_image_url,first_name,last_name,nickname,date_of_birth,blood_group,address,phone,contact_email,social_links,talents,motto,nationality,ethnicity,religion,school,plan,gpax,custom_fields,age_mode,manual_age FROM pg_catalog.jsonb_populate_recordset(NULL::public.profiles,snapshot->'profiles');
INSERT INTO public.activities(portfolio_id,title,description,images) SELECT new_id,title,description,images FROM pg_catalog.jsonb_populate_recordset(NULL::public.activities,snapshot->'activities');
INSERT INTO public.certificates(portfolio_id,title,description,image_url) SELECT new_id,title,description,image_url FROM pg_catalog.jsonb_populate_recordset(NULL::public.certificates,snapshot->'certificates');
INSERT INTO public.educations(portfolio_id,level,school_name,major,gpa) SELECT new_id,level,school_name,major,gpa FROM pg_catalog.jsonb_populate_recordset(NULL::public.educations,snapshot->'educations');
INSERT INTO public.portfolio_educations(portfolio_id,education_id,sort_order,snapshot_data,snapshot_revision,snapshot_version) SELECT new_id,education_id,sort_order,snapshot_data,snapshot_revision,snapshot_version FROM pg_catalog.jsonb_populate_recordset(NULL::public.portfolio_educations,snapshot->'portfolio_educations');
INSERT INTO public.portfolio_activities(portfolio_id,activity_id,sort_order,snapshot_data,snapshot_revision,snapshot_version) SELECT new_id,activity_id,sort_order,snapshot_data,snapshot_revision,snapshot_version FROM pg_catalog.jsonb_populate_recordset(NULL::public.portfolio_activities,snapshot->'portfolio_activities');
INSERT INTO public.portfolio_certificates(portfolio_id,certificate_id,sort_order,snapshot_data,snapshot_revision,snapshot_version) SELECT new_id,certificate_id,sort_order,snapshot_data,snapshot_revision,snapshot_version FROM pg_catalog.jsonb_populate_recordset(NULL::public.portfolio_certificates,snapshot->'portfolio_certificates');
INSERT INTO public.portfolio_section_visibility(portfolio_id,section,visible) SELECT new_id,section,visible FROM pg_catalog.jsonb_populate_recordset(NULL::public.portfolio_section_visibility,snapshot->'portfolio_section_visibility');
  END IF;
  outcome:='confirmed';
 END IF;
 INSERT INTO public.portfolio_action_receipts(user_id,request_id,action,source_id,title,status,portfolio_id) VALUES(actor,p_request_id,p_action,p_source_id,p_title,outcome,new_id) RETURNING * INTO receipt;
 RETURN pg_catalog.to_jsonb(receipt)-'user_id'-'created_at';
END $$;
REVOKE ALL ON FUNCTION public.perform_portfolio_action(uuid,text,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.perform_portfolio_action(uuid,text,uuid,text) TO authenticated;
NOTIFY pgrst,'reload schema';

-- Source: snapshot-storage-retention.sql SHA256 a2bce53f56be3e883cee56fce05d4de669f1029da699eb628c8952534735ad28
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname='storage' AND c.relname='objects' AND c.relrowsecurity) THEN
  RAISE EXCEPTION 'Storage objects with RLS required' USING ERRCODE='55000';
 END IF;
END $$;
-- Restrictive policies AND with existing permissive owner policies. They grant nothing.
-- PUBLIC covers every non-bypass role, even if a broad permissive policy is added later.
CREATE POLICY portfolio_images_immutable_update ON storage.objects
 AS RESTRICTIVE FOR UPDATE TO PUBLIC
 USING (bucket_id <> 'portfolio-images')
 WITH CHECK (bucket_id <> 'portfolio-images');
CREATE POLICY portfolio_images_retained_delete ON storage.objects
 AS RESTRICTIVE FOR DELETE TO PUBLIC
 USING (bucket_id <> 'portfolio-images');
-- SELECT / INSERT remain governed by existing policies. Other buckets are unchanged.
-- Owner/BYPASSRLS/service-role access is not blocked; never use it in the browser.
-- No physical file deletion, metadata mutation, or existing policy removal here.

NOTIFY pgrst, 'reload schema';
COMMIT;
